// Panel sites: every page is made of panels; each panel has 5 layouts to toggle through and a motion level.
// Layouts come from Erika's "Website mockup with swappable panels" (lib/panel-tpl.js, generated by tools/conv.py).
// Colors are the client's Brand Command colors, kept to WCAG AA; words come from the Senior Writer (or, before the
// pages are written, from Brand Command itself); images are Brand Command images.
import { RAW, LAYOUT_NAMES, ICONS, HOVER_CSS } from './panel-tpl.js';
import { readable, contrast, lum, esc } from './site-kit.js';

export { LAYOUT_NAMES };
export const FAMILIES = ['hero', 'offer', 'show', 'proof', 'convert'];
export const FAMILY_LABEL = { hero: 'Hero', offer: 'Services', show: 'Showcase', proof: 'Proof', convert: 'Call to action' };
// Which panel family each kind of section uses (other sections keep the standard layout).
export const FAMILY_OF = { hero: 'hero', features: 'offer', services: 'offer', values: 'offer', agenda: 'offer', categories: 'offer', cases: 'show', products: 'show', posts: 'show', resources: 'show', stats: 'proof', testimonials: 'proof', cta: 'convert', contact: 'convert', leadform: 'convert', subscribe: 'convert' };
export const MOTION = [['0', 'None'], ['1', 'Subtle'], ['2', 'Lively'], ['3', 'Max']];

// ---- design styles: how the brand is dressed (type, corners, background tone) ----
export const STYLES = {
  editorial: { label: 'Editorial', serif: true, dw: 400, dls: '-0.01em', r: '4px', bg: 'warm' },
  classic: { label: 'Classic', serif: true, dw: 400, dls: '0', r: '0px', bg: 'white' },
  modern: { label: 'Modern', serif: false, dw: 800, dls: '-0.03em', r: '14px', bg: 'cool' },
  bold: { label: 'Bold', serif: false, dw: 900, dls: '-0.04em', r: '0px', bg: 'white' },
  soft: { label: 'Soft', serif: false, dw: 700, dls: '-0.02em', r: '22px', bg: 'tint' },
  minimal: { label: 'Minimal', serif: false, dw: 600, dls: '-0.02em', r: '6px', bg: 'white' },
};
// ---- industries (Brand Command's industry decides which designs come first) ----
const IND = [
  ['fin', /financ|wealth|advis|bank|invest|insur|account|ria\b|capital|tax/i, ['editorial', 'classic', 'modern', 'minimal', 'soft', 'bold']],
  ['tech', /tech|software|saas|data|\bai\b|cyber|digital|cloud|\bit\b/i, ['modern', 'bold', 'minimal', 'soft', 'editorial', 'classic']],
  ['health', /health|medic|dental|clinic|wellness|care|pharma|therap|life science/i, ['soft', 'modern', 'minimal', 'editorial', 'classic', 'bold']],
  ['re', /real estate|property|realt|mortgage|construct|architect|home/i, ['editorial', 'classic', 'bold', 'modern', 'soft', 'minimal']],
  ['mfg', /manufactur|industrial|engineer|logistic|auto|aerospace/i, ['bold', 'modern', 'minimal', 'classic', 'editorial', 'soft']],
  ['energy', /energy|sustain|solar|utility|climate|environment/i, ['modern', 'bold', 'soft', 'minimal', 'editorial', 'classic']],
  ['edu', /educat|school|university|learn|training|coach/i, ['soft', 'modern', 'editorial', 'minimal', 'bold', 'classic']],
  ['retail', /retail|consumer|food|restaurant|hospitality|beauty|fashion|shop|ecommerce/i, ['bold', 'soft', 'modern', 'minimal', 'editorial', 'classic']],
  ['np', /nonprofit|non-profit|charity|foundation|philanthrop|community|church/i, ['soft', 'editorial', 'modern', 'classic', 'minimal', 'bold']],
  ['pro', /legal|law|attorney|consult|professional|services|agency|marketing/i, ['editorial', 'minimal', 'classic', 'modern', 'bold', 'soft']],
];
export function industryKey(industry) { const hit = IND.find((x) => x[1].test(String(industry || ''))); return hit ? hit[0] : 'pro'; }
const hash = (s) => { let h = 7; String(s).split('').forEach((c) => { h = (h * 31 + c.charCodeAt(0)) >>> 0; }); return h; };
// Several designs for each type of site and each industry: a style plus a layout for every panel.
export function designOptions(type, industry, n = 6) {
  const key = industryKey(industry), order = (IND.find((x) => x[0] === key) || IND[IND.length - 1])[2];
  const h = hash(type + '|' + key), off = FAMILIES.map((f, i) => (h >>> (i * 3)) % 5);
  return Array.from({ length: n }, (_, k) => {
    const style = order[k % order.length];
    const w = k >= 5 ? 1 : 0; // the 6th design never repeats the 1st
    const lay = { hero: (off[0] + k + 2 * w) % 5, offer: (off[1] + 2 * k + w) % 5, show: (off[2] + 3 * k + w) % 5, proof: (off[3] + k + w) % 5, convert: (off[4] + 2 * k + 1 + 2 * w) % 5 };
    return { id: 'd' + k, style, lay, solid: SOLID_PLAN[(k + (h % 3)) % SOLID_PLAN.length], name: STYLES[style].label + ' · ' + LAYOUT_NAMES.hero[lay.hero] + ' hero', industry: key };
  });
}

// ---- theme: CSS variables the panels use, from the brand and the style, every text pair at least 4.5:1 ----
const hx = (c) => { const m = String(c || '').match(/^#?([0-9a-f]{6})$/i); return m ? '#' + m[1].toUpperCase() : null; };
const mixc = (a, b, t) => { const A = [1, 3, 5].map((i) => parseInt(a.substr(i, 2), 16)), B = [1, 3, 5].map((i) => parseInt(b.substr(i, 2), 16)); return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join('').toUpperCase(); };
const darkUntil = (c, test) => { let x = c; for (let i = 0; i < 12 && !test(x); i++) x = mixc(x, '#000000', 0.12); return x; };
const both = (a, b, cands) => { for (const c of cands.filter(Boolean)) if (contrast(c, a) >= 4.5 && contrast(c, b) >= 4.5) return c; return darkUntil(cands[0] || '#333333', (x) => contrast(x, a) >= 4.5 && contrast(x, b) >= 4.5); };
export function panelTheme(brand, styleId) {
  const S = STYLES[styleId] || STYLES.modern;
  const cols = [brand.primary, brand.secondary, brand.accent].concat(brand.colors || []).map(hx).filter(Boolean);
  const darkest = cols.slice().sort((a, b) => lum(a) - lum(b))[0] || '#0E2266';
  const p0 = hx(brand.primary) || darkest;
  // Primary bands and buttons carry white text, including 70%-white small text.
  const primary = darkUntil(lum(p0) < 0.2 ? p0 : darkest, (x) => contrast('#FFFFFF', x) >= 4.5 && contrast(mixc(x, '#FFFFFF', 0.7), x) >= 4.5);
  const bg = S.bg === 'white' ? '#FFFFFF' : S.bg === 'warm' ? mixc(mixc(p0, '#C8A35A', 0.5), '#FFFFFF', 0.92) : S.bg === 'cool' ? mixc(p0, '#FFFFFF', 0.95) : mixc(hx(brand.secondary) || p0, '#FFFFFF', 0.9);
  const paper = '#FFFFFF';
  const ink = both(bg, paper, ['#0E1A2B', mixc(darkest, '#000000', 0.4), '#111111']);
  const muted = both(bg, paper, ['#4D5767', '#454B57', '#3A3F4A']);
  // Accent: the brand's highlight; readable as text on primary bands, with its own readable text on top.
  const acc0 = hx(brand.accent) || hx(brand.secondary) || '#C8A35A';
  const accent = contrast(acc0, primary) >= 4.5 ? acc0 : readable(primary, [acc0, mixc(acc0, '#FFFFFF', 0.4), '#FFFFFF'], 4.5);
  const onAccent = readable(accent, ['#FFFFFF', ink, '#111111'], 4.5);
  const display = S.serif ? "'DM Serif Display',Georgia,serif" : "'" + (brand.head || 'Manrope') + "',system-ui,sans-serif";
  const sc = [1, 3, 5].map((i) => parseInt(ink.substr(i, 2), 16)).join(',');
  return { '--bg': bg, '--paper': paper, '--ink': ink, '--muted': muted, '--primary': primary, '--accent': accent, '--onAccent': onAccent, '--heroBg': bg, '--display': display, '--dw': String(S.dw), '--dls': S.dls, '--r': S.r, '--scrim': sc, serif: S.serif };
}
// ---- solid panels: a dark brand color (primary or secondary shade) with reversed (light) text, every pair at least 4.5:1 ----
export const SOLID = [['', 'Light'], ['p', 'Brand color'], ['s', 'Second color']];
export function solidTheme(brand, base, which) {
  const okW = (x) => contrast('#FFFFFF', x) >= 4.5 && contrast(mixc(x, '#FFFFFF', 0.72), x) >= 4.5;
  const pri = base['--primary'];
  const sec0 = [brand.secondary, brand.accent].concat(brand.colors || []).map(hx).filter(Boolean).find((c) => c !== hx(brand.primary));
  let bg = which === 's' && sec0 ? darkUntil(sec0, okW) : pri;
  if (which === 's' && contrast(bg, pri) < 1.3) bg = darkUntil(mixc(bg, '#000000', 0.3), okW);
  if (which === 's' && contrast(bg, pri) < 1.3) bg = mixc(pri, '#FFFFFF', 0.18);
  if (!okW(bg)) bg = darkUntil(bg, okW);
  const paper = darkUntil(mixc(bg, '#FFFFFF', 0.08), okW);
  let muted = '#FFFFFF'; for (const t of [0.78, 0.84, 0.9, 0.95]) { const m = mixc(bg, '#FFFFFF', t); if (contrast(m, bg) >= 4.5 && contrast(m, paper) >= 4.5) { muted = m; break; } }
  const primary = mixc(bg, '#000000', 0.35);
  const okAll = (c) => [bg, paper, primary].every((x) => contrast(c, x) >= 4.5);
  const acc0 = hx(brand.accent) || sec0 || '#C8A35A';
  const accent = [acc0, mixc(acc0, '#FFFFFF', 0.35), mixc(acc0, '#FFFFFF', 0.6), '#FFFFFF'].find(okAll) || '#FFFFFF';
  const onAccent = readable(accent, ['#FFFFFF', '#0E1A2B', '#111111'], 4.5);
  return { '--bg': bg, '--heroBg': bg, '--paper': paper, '--ink': '#FFFFFF', '--muted': muted, '--primary': primary, '--accent': accent, '--onAccent': onAccent };
}
// Which panels are solid in each design option (people's choice per panel beats this).
export const SOLID_PLAN = [{ offer: 'p', convert: 's' }, { hero: 'p', show: 's' }, { hero: 's', show: 'p', convert: 's' }, { offer: 'p', proof: 's', convert: 'p' }, { hero: 'p', offer: 's', convert: 'p' }, { offer: 's', proof: 'p', convert: 'p' }];
export const themeCss = (th) => Object.keys(th).filter((k) => k.startsWith('--')).map((k) => k + ':' + th[k]).join(';');

// ---- words for a panel (V), from the section's content ----
const ICON_HINT = [[/bank|financ|money|wealth|capital/i, 0], [/invest|growth|grow|chart|result/i, 1], [/plan|strategy|map/i, 2], [/protect|insur|secur|risk|safe/i, 3]];
const iconFor = (title, i) => { const hit = ICON_HINT.find((x) => x[0].test(title || '')); return ICONS[(hit ? hit[1] : i) % ICONS.length]; };
const arr = (x) => (Array.isArray(x) ? x : []);
export function panelVals(kind, c, si, ctx) {
  const fam = FAMILY_OF[kind]; c = c || {};
  const e = (f) => si + '.' + f;
  const B = { name: ctx.brandName, mark: String(ctx.brandName || '?').trim()[0] || '?', tagline: ctx.tagline || '', email: ctx.email || '', phone: ctx.phone || '', heroPh: '', ctaPh: '' };
  const V = { B, T: { cta: c.cta || 'Contact us', cta1: c.cta || 'Get started', cta2: ctx.cta2 || 'Learn more', nav: [], offer: {}, show: {}, proof: {}, convert: {} }, H: {}, Q: {}, img: { hero: ctx.photo(0), proof: ctx.photo(1), convert: ctx.photo(2) }, offers: [], items: [], stats: ctx.stats || [], logos: [], _e: {}, _href: ctx.ctaHref || '#', _form: ctx.formAction || '#' };
  if (fam === 'hero') { V.H = { eyebrow: c.eyebrow || '', title: c.headline || '', body: c.body || '' }; V._e = { 'H.eyebrow': e('eyebrow'), 'H.title': e('headline'), 'H.body': e('body'), 'T.cta1': e('cta') }; }
  if (fam === 'offer') {
    V.T.offer = { eyebrow: c.eyebrow || '', title: c.heading || '', body: c.intro || '', link: 'Learn more' }; V._e = { 'T.offer.eyebrow': e('eyebrow'), 'T.offer.title': e('heading'), 'T.offer.body': e('intro') };
    V.offers = arr(c.items).filter((x) => x && (x.title || x.text)).map((x, i) => ({ n: (i < 9 ? '0' : '') + (i + 1), title: x.title || '', desc: x.text || '', icon: iconFor(x.title, i), img: ctx.photo(i + 1), ph: '', _e: { title: e('items.' + i + '.title'), desc: e('items.' + i + '.text') } }));
  }
  if (fam === 'show') {
    V.T.show = { eyebrow: c.eyebrow || '', title: c.heading || '', body: c.intro || '', action: kind === 'products' ? 'View' : 'Read more' }; V._e = { 'T.show.eyebrow': e('eyebrow'), 'T.show.title': e('heading'), 'T.show.body': e('intro') };
    V.items = arr(c.items).filter(Boolean).map((x, i) => {
      const it = kind === 'cases' ? { kicker: 'Case study', title: x.title, sub: x.challenge, meta: x.result, f: ['title', 'challenge', 'result'] }
        : kind === 'products' ? { kicker: '', title: x.name, sub: x.text, meta: x.price, f: ['name', 'text', 'price'] }
        : kind === 'posts' ? { kicker: x.category, title: x.title, sub: x.text, meta: '', f: ['title', 'text', ''] }
        : { kicker: x.type, title: x.title, sub: x.text, meta: '', f: ['title', 'text', ''] };
      return { kicker: it.kicker || '', title: it.title || '', sub: it.sub || '', meta: it.meta || '', img: ctx.photo(i + 1), ph: '', _e: { title: e('items.' + i + '.' + it.f[0]), sub: e('items.' + i + '.' + it.f[1]), meta: it.f[2] ? e('items.' + i + '.' + it.f[2]) : '' } };
    });
  }
  if (fam === 'proof') {
    V.T.proof = { eyebrow: c.eyebrow || '', title: c.heading || '', body: c.intro || '' }; V._e = { 'T.proof.title': e('heading') };
    if (kind === 'stats') V.stats = arr(c.items).filter((x) => x && x.value).map((x) => ({ v: x.value, l: x.label || '' }));
    const q = kind === 'testimonials' ? arr(c.items).find((x) => x && x.quote) : ctx.quote;
    V.Q = q ? { text: q.quote, who: q.name || '', role: q.role || '' } : { text: '', who: '', role: '' };
  }
  if (fam === 'convert') {
    const fields = kind === 'contact' ? ['Full name', 'Email', 'Company', 'How can we help?'] : kind === 'leadform' ? ['Full name', 'Work email', 'Company'] : ['Email address'];
    V.T.convert = { eyebrow: c.eyebrow || '', title: c.heading || '', body: c.body || '', btn: c.cta || 'Get in touch', fields, placeholder: 'Email address', thanks: 'we’ll be in touch soon.' };
    V._e = { 'T.convert.eyebrow': e('eyebrow'), 'T.convert.title': e('heading'), 'T.convert.body': e('body') };
  }
  V.stat0 = V.stats[0] || { v: '', l: '' };
  return V;
}
// Is there anything to show? Proof without Brand Command numbers or quotes stays hidden (nothing is invented).
export function panelHasContent(kind, V) { const f = FAMILY_OF[kind]; if (f === 'proof') return !!(V.stats.length || (V.Q && V.Q.text)); if (f === 'show') return V.items.length > 0; if (f === 'offer') return V.offers.length > 0; return true; }

// ---- render one panel (all of its states for tabs, carousels and forms) ----
const get = (o, p) => String(p).split('.').reduce((x, k) => (x == null ? x : x[k]), o);
function helpers(preview) {
  const t = (o, p) => { const v = get(o, p); const path = o && o._e && o._e[p]; return preview && path ? '<span data-edit="' + path + '">' + esc(v) + '</span>' : esc(v); };
  const a = (v) => esc(v);
  const img = (src, ph) => (src ? '<img src="' + esc(src) + '" alt="" data-pimg style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover">' : '<div aria-hidden="true" style="position:absolute;inset:0;background:linear-gradient(135deg,var(--bg),color-mix(in oklab,var(--primary) 18%,var(--bg)))"></div>');
  return { t, a, img };
}
export function renderPanel(kind, layout, V, opts = {}) {
  const fam = FAMILY_OF[kind]; const tpl = RAW[fam] && RAW[fam][layout % 5]; if (!tpl) return '';
  const H = helpers(!!opts.preview); const src = tpl.toString();
  const mk = (st, extra) => tpl(Object.assign({}, V, extra, { _st: st }), H);
  // Tabs (one pane per service), carousels (one slide per item), forms (form, then thanks).
  if (/offerActive|o\.active/.test(src) && V.offers.length > 1) return states(V.offers.map((o, st) => mk(st, { offers: V.offers.map((x, i) => Object.assign({}, x, { active: i === st, idle: i !== st })), offerActive: V.offers[st] })));
  if (/V\._n|V\.cur/.test(src) && V.items.length > 1) return states(V.items.map((x, st) => mk(st, { _n: V.items.length, cur: Object.assign({}, x, { pos: (st + 1) + ' / ' + V.items.length }) })));
  if (/V\.notSent/.test(src)) return states([mk(0, { notSent: true, sent: false }), mk(1, { notSent: false, sent: true })]);
  const base = { offFirst: V.offers[0] || {}, offRest: V.offers.slice(1), featured: V.items[0] || {}, rest: V.items.slice(1), cur: V.items[0] || {}, offerActive: V.offers[0] || {}, notSent: true, sent: false, _n: V.items.length || 1 };
  return mk(0, Object.assign(base, { offers: V.offers.map((x, i) => Object.assign({}, x, { active: i === 0, idle: i !== 0 })) }));
}
function states(list) { return '<div data-states>' + list.map((h, i) => '<div data-state="' + i + '"' + (i ? ' hidden' : '') + '>' + h + '</div>').join('') + '</div>'; }

// ---- motion: none → max, per panel. Off for anyone who asks for reduced motion. ----
export const PANEL_CSS = HOVER_CSS + `
.pnl{position:relative}.pnl section{position:relative}
.pnl [data-pimg]{transition:transform .9s cubic-bezier(.2,.7,.2,1)}
[data-motion="1"] .rv,[data-motion="2"] .rv,[data-motion="3"] .rv{opacity:0;transition:opacity .7s ease,transform .8s cubic-bezier(.2,.7,.2,1)}
[data-motion="1"] .rv{transform:translateY(12px)}[data-motion="2"] .rv{transform:translateY(28px)}[data-motion="3"] .rv{transform:translateY(48px) scale(.98)}
.pnl .rv.in{opacity:1;transform:none}
[data-motion="2"] a:hover,[data-motion="3"] a:hover{transform:translateY(-2px)}[data-motion="2"] a,[data-motion="3"] a{transition:transform .25s ease,opacity .25s}
[data-motion="2"] li:hover,[data-motion="3"] li:hover,[data-motion="3"] article:hover{transform:translateY(-4px)}[data-motion="2"] li,[data-motion="3"] li,[data-motion="3"] article{transition:transform .3s ease}
[data-motion="2"] *:hover>[data-pimg],[data-motion="3"] *:hover>[data-pimg]{transform:scale(1.04)}
[data-motion="3"] [data-pimg]{animation:pnl-kb 18s ease-in-out infinite alternate}
@keyframes pnl-kb{from{transform:scale(1)}to{transform:scale(1.08)}}
.pnl[data-solid] input,.pnl[data-solid] textarea,.pnl[data-solid] select{background:#FFFFFF!important;color:#0E1A2B!important}
@media (prefers-reduced-motion:reduce){.pnl .rv{opacity:1!important;transform:none!important;transition:none!important}.pnl *{animation:none!important;transition:none!important}}`;
// One small script per page: panel states (tabs, slides, forms) and motion (reveal on scroll, parallax at Max).
export const PANEL_JS = `(function(){var R=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
document.addEventListener('click',function(e){var g=e.target.closest('[data-go]');if(!g)return;var w=g.closest('[data-states]');if(!w)return;e.preventDefault();var to=g.getAttribute('data-go');[].forEach.call(w.children,function(c){c.hidden=c.getAttribute('data-state')!==to;});var f=w.querySelector('[data-state="'+to+'"] button,[data-state="'+to+'"] a');if(f&&g.matches('[role=tab],button'))f.focus({preventScroll:true});});
document.addEventListener('submit',function(e){var f=e.target;if(!f.matches('[data-submit]'))return;var w=f.closest('[data-states]');if(f.getAttribute('action')==='#'||!f.getAttribute('action')){e.preventDefault();if(w){[].forEach.call(w.children,function(c){c.hidden=c.getAttribute('data-state')!=='1';});}}});
function prep(){document.querySelectorAll('.pnl').forEach(function(p){var m=+p.getAttribute('data-motion')||0;p.querySelectorAll('.rv').forEach(function(x){x.classList.remove('rv','in');});if(!m||R)return;p.querySelectorAll('h1,h2,h3,p,blockquote,ul>li,ol>li,section>div>div,form,a').forEach(function(x,i){if(x.closest('.rv'))return;x.classList.add('rv');x.style.transitionDelay=(m>1?Math.min(i,8)*60:0)+'ms';});});
var io=('IntersectionObserver' in window)?new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target);}});},{threshold:.12}):null;document.querySelectorAll('.rv').forEach(function(x){io?io.observe(x):x.classList.add('in');});}
window.__pnlPrep=prep;prep();
if(!R)window.addEventListener('scroll',function(){document.querySelectorAll('.pnl[data-motion="3"] [data-pimg]').forEach(function(im){var r=im.parentNode.getBoundingClientRect();var d=(r.top+r.height/2-innerHeight/2)/innerHeight;im.style.translate='0 '+(d*-24).toFixed(1)+'px';});},{passive:true});})();`;
